const item = $input.all()[0].json;
const body = item.email_body || '';

let pdfPassword = '';
const match = body.match(/password[^"'\n]*["']([^"']+)["']/i) || body.match(/password\s*(?:is|:)\s*([A-Za-z0-9@#$%^&*!]+)/i);
if (match) pdfPassword = match[1];

// FIX: some sub-workflow calls have delivered this as 'file_id' (singular)
// instead of the declared 'file_ids' (plural) -- fall back to either so a
// naming mismatch upstream never silently drops a real submission again.
const rawIds = item.file_ids || item.file_id || '';
const ids = String(rawIds).split(',').map(s => s.trim()).filter(Boolean);

return ids.map(id => ({
  json: {
    ...item,
    file_id: id,
    client_email: item.client_email,
    client_name: item.client_name || 'Unknown',
    itr_type: item.itr_type,
    client_dob: item.client_dob,
    pdf_password: pdfPassword
  }
}));

const inputItems = $input.all();
const output = [];

for (const inputItem of inputItems) {
  const item = inputItem.json;
  const binary = inputItem.binary ? inputItem.binary.data : undefined;
  let password = item.pdf_password || '';

  const dobDigits = (item.client_dob || '').replace(/[^0-9]/g, '');
  const dob = dobDigits.length > 0 && dobDigits.length < 8 ? dobDigits.padStart(8, '0') : dobDigits;

  if (!password && item.pan_number && dob.length === 8) {
    // FIX: prefer the client's actual declared PAN (from the intake form / Form 16)
    // over guessing from the filename. AIS statement filenames from the income tax
    // portal often mask the PAN for privacy (e.g. 'XXXPK8880X'), which previously
    // produced a wrong password guess and made the AIS PDF fail to extract entirely.
    password = String(item.pan_number).toLowerCase() + dob;
  }

  if (!password) {
    const fileName = (binary && binary.fileName) || '';
    const idMatch = fileName.match(/[A-Z]{5}[0-9]{4}[A-Z]/i);
    if (idMatch && dob.length === 8 && !/^X+$/i.test(idMatch[0].replace(/[0-9]/g, ''))) {
      // only trust a filename-derived PAN if it isn't masked with X's
      password = idMatch[0].toLowerCase() + dob;
    }
  }

  output.push({ json: { ...item, pdf_password: password }, binary: inputItem.binary });
}

return output;

const item = $input.all()[0].json;
// Raised from 10,000 to 40,000 chars: client uploads often combine Form 16
// AND an AIS/other-income statement in one PDF, and the smaller cap was
// silently truncating the AIS pages, which is why "other income" was going
// unseen and tax was coming out understated (or nil). Correctness on the
// tax figure matters more than the small extra token cost here.
const pdfText = (item.text || '').slice(0, 40000);

function amt(v) { const n = parseFloat(v); return isNaN(n) ? 0 : n; }

const declaredLines = [];
if (item.pan_number) declaredLines.push('PAN: ' + item.pan_number);
if (item.assessment_year) declaredLines.push('Assessment Year: ' + item.assessment_year);
if (item.financial_year) declaredLines.push('Financial Year: ' + item.financial_year);
if (amt(item.deduction_80c) > 0) declaredLines.push('Client-declared Section 80C investment: Rs.' + amt(item.deduction_80c));
if (amt(item.deduction_80d) > 0) declaredLines.push('Client-declared Section 80D premium: Rs.' + amt(item.deduction_80d));
if (amt(item.deduction_80tta_ttb) > 0) declaredLines.push('Client-declared Section 80TTA/80TTB interest: Rs.' + amt(item.deduction_80tta_ttb));
if (amt(item.hra_amount) > 0) declaredLines.push('Client-declared annual HRA received: Rs.' + amt(item.hra_amount));
if (amt(item.home_loan_interest_24b) > 0) declaredLines.push('Client-declared Section 24(b) home loan interest: Rs.' + amt(item.home_loan_interest_24b));
if (amt(item.deduction_80ccd_1b) > 0) declaredLines.push('Client-declared Section 80CCD(1B) NPS contribution: Rs.' + amt(item.deduction_80ccd_1b));

const clientDeclaredBlock = declaredLines.length
  ? '\n\nClient-declared figures from the intake form (cross-check these against the document; if the document shows a different figure, use the document\'s actual figure and note the discrepancy in \'flags\' or \'disclosure_flags\'):\n' + declaredLines.map(l => '- ' + l).join('\n')
  : '';

const kbVerificationInstruction = "MANDATORY VERIFICATION OF TAX FIGURES -- KNOWLEDGE BASE FIRST, OFFICIAL WEBSITE ONLY AS FALLBACK, NEVER GENERAL WEB RESULTS -- BE EFFICIENT, MINIMIZE TOOL CALLS: You have three tools -- Tax Knowledge Base Tool (Supabase, always checked first), Search Income Tax Website (Tavily), and Cache Tax Info in Knowledge Base. The ONLY two sources you may ever cite a tax figure from are: (a) content already present in the Tax Knowledge Base (populated by earlier searches or manual ingestion), or (b) a live Tavily search whose query is explicitly restricted to site:incometaxindia.gov.in or site:egazette.gov.in. Never cite, rely on, or blend in a figure from any other website, general search result, or your own unverified memory. Do NOT verify figures one at a time. Before writing your final answer: (1) Identify the small list of numeric tax figures this specific case actually depends on (usually just the applicable regime slabs, the deduction sections present in this document/client data, and any relevant rebate/LTCG limit -- normally 1-3 items total, not one per section). (2) Call the Tax Knowledge Base Tool AT MOST ONCE with a single combined query covering all of those items together -- this is checking whether the figure was already fetched by a prior live search or manual ingestion, so you never repeat work someone already did. (3) Only for whichever items that KB call does NOT confirm, call the Tavily search tool AT MOST ONCE with a single combined query covering everything still unconfirmed, with the query text explicitly restricted to site:incometaxindia.gov.in or site:egazette.gov.in -- disregard any result from a domain other than these two, even if it appears relevant. (4) If the live search returns clear, verified content from an official source, call the Cache Tax Info in Knowledge Base tool ONCE to save it (combine multiple confirmed items into one cache call when practical) before finishing -- this is not optional when you used live search successfully, and is what makes the next client's question on the same topic instant instead of needing another web search. (5) If a figure remains unconfirmed after both the knowledge base and an official-site search, do not silently present it as certain -- give your best answer using your own knowledge, but add an entry to the 'flags' (or 'disclosure_flags') array: 'UNVERIFIED: <figure/section> could not be confirmed against the knowledge base or a live official source -- please verify manually before filing.' Well-established constants already listed below under 'Known reference points' do NOT need a separate tool call unless you have specific reason to doubt they still apply for the relevant Assessment Year. Target at most one Knowledge Base call, one Tavily call, and one Cache call per report -- never call the same tool repeatedly for individual figures.";

const totalIncomeInstruction = "CRITICAL -- TOTAL INCOME MUST INCLUDE EVERY SOURCE IN THE DOCUMENT, NOT SALARY ALONE: Carefully scan the ENTIRE extracted document text -- not just the first page -- for every income disclosure. This includes Form 16 salary AND any AIS (Annual Information Statement), Form 26AS, TIS, or interest/dividend certificate content showing savings/FD/RD interest, dividends, rental income, or any other 'Income from Other Sources' receipts. If any such other-income entries are present anywhere in the document, they are NOT optional extras -- you MUST add them to Gross Total Income before computing tax under either regime, because they change the actual tax payable. If, after a careful full-document scan, you find no other-income disclosures beyond salary, explicitly write 'No other income identified beyond salary in the document provided' in the computation rather than silently assuming zero. Never state a conclusion of 'no tax payable', 'nil tax', or similar without first showing the COMPLETE line-by-line computation for BOTH regimes in the tax_computation object described below -- the computation must visibly walk through: Gross Salary -> Less Standard Deduction -> Add Income from Other Sources -> Gross Total Income -> Less Chapter VI-A Deductions (80C/80D/80TTA-TTB/80CCD(1B) etc, Old Regime only unless the document indicates otherwise) -> Net Taxable Income -> Tax as per applicable slab -> Less Section 87A rebate if eligible -> Add Health & Education Cess (4%) -> Total Tax Payable.";

const taxSavingScenarioInstruction = "TAX-SAVING SCENARIOS (MANDATORY WHENEVER A CHAPTER VI-A DEDUCTION LIMIT IS NOT FULLY USED): For every deduction limit the client has not fully utilised (Section 80C up to Rs.1,50,000, Section 80D, Section 80CCD(1B) up to Rs.50,000, Section 80TTA/80TTB, etc, under the Old Regime), add one entry to 'tax_saving_scenarios' showing: the section, a plain-English description of the concrete step (e.g. 'Investing a further Rs.X in ELSS/PPF/EPF/life insurance under Section 80C'), the additional_eligible_amount they could still invest/spend, and an estimated_tax_saved computed as that additional amount multiplied by the client's marginal tax rate under the regime where the deduction applies -- show the arithmetic briefly inside the description so it can be independently rechecked (e.g. 'Rs.1,00,000 x 20% slab + 4% cess = approx Rs.20,800 saved'). Only include scenarios that are actually available to this client's profession/income type.";

const futurePlanningInstruction = "FUTURE TAX PLANNING (MANDATORY, LEGAL METHODS ONLY): Based on this specific client's income profile, list 3 to 6 legally compliant ways they could reduce tax in future years in 'future_tax_planning' -- for example fully using Section 80C via ELSS/PPF/EPF/life insurance, an additional Section 80CCD(1B) NPS contribution, Section 80D health insurance for self/family/parents, re-evaluating Old vs New regime choice each year since the more beneficial one can change, HRA and home-loan-interest planning if applicable, or advance tax planning if other income is likely to recur. Every suggestion must be legitimate tax planning, never evasion or misreporting. End this section by explicitly stating that these limits, rates and rules apply for the relevant Assessment Year only and are SUBJECT TO CHANGE in future Finance Acts, so they must be reconfirmed before being relied on in a later year.";

const taxRulesReference = "Apply Indian Income Tax Act provisions accurately for the relevant Assessment Year based on dates in the document. Ground every figure strictly in the data actually present in the extracted text -- never invent numbers. Where document data is insufficient to compute an exact figure, say so explicitly rather than guessing. Cite the specific Section of the Income Tax Act for every deduction, exemption, or provision mentioned (e.g. Section 80C, Section 54). " + totalIncomeInstruction + " " + kbVerificationInstruction + " " + taxSavingScenarioInstruction + " " + futurePlanningInstruction + " Known reference points to apply, but VERIFY against the Finance Act applicable to the relevant Assessment Year and flag in 'flags' or 'disclosure_flags' if you are uncertain whether a rate/slab has since changed: New Regime slabs (recent years): Nil up to Rs.3,00,000; 5% Rs.3,00,001-7,00,000; 10% Rs.7,00,001-10,00,000; 15% Rs.10,00,001-12,00,000; 20% Rs.12,00,001-15,00,000; 30% above Rs.15,00,000; standard deduction Rs.75,000 for salaried/pensioners; Section 87A rebate making tax nil up to Rs.7,00,000 taxable income (marginal relief applies). Old Regime slabs: Nil up to Rs.2,50,000; 5% Rs.2,50,001-5,00,000; 20% Rs.5,00,001-10,00,000; 30% above Rs.10,00,000; Section 87A rebate up to Rs.5,00,000 taxable income. Section 80C limit Rs.1,50,000. Section 80D: Rs.25,000 (self/family, non-senior), Rs.50,000 (senior citizen). Section 80TTA: Rs.10,000 (savings interest, non-senior). Section 80TTB: Rs.50,000 (senior citizen, all interest). Listed equity shares/equity mutual funds: LTCG exemption up to Rs.1,25,000 per year, taxed at 12.5% above that (no indexation); STCG taxed at 20%. Section 54: LTCG exemption on sale of residential house if reinvested in a new residential house within the prescribed period. Section 54F: exemption on LTCG from sale of any asset other than a house, if invested in a residential house. Section 54EC: exemption by investing capital gains (up to Rs.50,00,000) in specified bonds (NHAI/REC/PFC) within 6 months. Always end with a clear, prominent recommendation of which ITR form applies and which tax regime is more beneficial for this specific client, based on the numbers actually computed.";

const taxComputationSchema = "\"tax_computation\":{\"old_regime\":{\"gross_salary\":number,\"standard_deduction\":number,\"income_from_other_sources\":number,\"gross_total_income\":number,\"chapter_via_deductions\":number,\"net_taxable_income\":number,\"tax_before_cess\":number,\"rebate_87A\":number,\"health_education_cess\":number,\"total_tax_payable\":number},\"new_regime\":{\"gross_salary\":number,\"standard_deduction\":number,\"income_from_other_sources\":number,\"gross_total_income\":number,\"chapter_via_deductions\":number,\"net_taxable_income\":number,\"tax_before_cess\":number,\"rebate_87A\":number,\"health_education_cess\":number,\"total_tax_payable\":number},\"other_income_note\":string},\"tax_saving_scenarios\":[{\"section\":string,\"description\":string,\"additional_eligible_amount\":number,\"estimated_tax_saved\":number}],\"future_tax_planning\":[string]";

const prompts = {
  'ITR-1': "You are a meticulous Chartered Accountant's assistant preparing a tax advisory note for a salaried individual filing ITR-1 in India. " + taxRulesReference + " Given the client's Form 16 data, any AIS/other-income details, and bank interest details in the extracted document text, do the following: 1) Compare total tax liability under the Old Regime vs New Regime with the actual computed numbers, showing the full computation in tax_computation as instructed above. 2) Identify unused deductions under 80C, 80D, 80TTA/80TTB, and HRA exemption if applicable, citing sections, and build tax_saving_scenarios for each. 3) Populate future_tax_planning with legal, forward-looking guidance. 4) Flag anything unusual, incomplete, or where you are uncertain about current rates. Respond ONLY with valid JSON, no other text: {\"recommended_itr_type\":\"ITR-1\",\"old_regime_tax\":number,\"new_regime_tax\":number,\"recommended_regime\":string,\"regime_reasoning\":string," + taxComputationSchema + ",\"deduction_gaps\":[{\"section\":string,\"unused_amount\":number,\"note\":string}],\"action_items\":[string],\"flags\":[string]}",
  'ITR-2': "You are a meticulous Chartered Accountant's assistant preparing a tax advisory note for an individual filing ITR-2 in India (capital gains / multiple properties / foreign assets, no business income). " + taxRulesReference + " Using the extracted document text, including any AIS/other-income details: 1) Compare Old vs New regime with computed numbers and deduction gaps (80C/80D/HRA), citing sections, showing the full computation in tax_computation as instructed above. 2) Calculate STCG and LTCG separately (equity vs non-equity, applying correct rates and the Rs.1,25,000 equity LTCG exemption) with indexation where legally eligible (non-equity assets under Section 48). 3) Check Section 54/54F/54EC exemption eligibility on any property sale, citing conditions. 4) Flag Schedule FA disclosure needs for any foreign assets. 5) Build tax_saving_scenarios and future_tax_planning as instructed above. Respond ONLY with valid JSON, no other text: {\"recommended_itr_type\":\"ITR-2\",\"old_regime_tax\":number,\"new_regime_tax\":number,\"recommended_regime\":string,\"regime_reasoning\":string,\"capital_gains\":{\"stcg\":number,\"ltcg\":number,\"indexed_ltcg\":number}," + taxComputationSchema + ",\"exemption_opportunities\":[{\"section\":string,\"estimated_saving\":number,\"note\":string}],\"deduction_gaps\":[{\"section\":string,\"unused_amount\":number,\"note\":string}],\"disclosure_flags\":[string],\"action_items\":[string]}",
  'ITR-3': "You are a meticulous Chartered Accountant's assistant preparing a tax advisory note for an individual filing ITR-3 in India (business/professional income, regular scheme). " + taxRulesReference + " Using the extracted P&L, balance sheet, GST text, and any AIS/other-income details: 1) Review claimed expenses for common missed deductions, citing sections. 2) Check the depreciation schedule under the block-of-assets method (Section 32) for correctness. 3) Compare tax liability to the presumptive scheme (Section 44AD/44ADA) if turnover qualifies, with computed numbers, showing the full computation in tax_computation (use regular_scheme and presumptive_scheme as the two keys instead of old_regime/new_regime, same line items). 4) Flag GST-vs-P&L turnover mismatches. 5) Build tax_saving_scenarios and future_tax_planning as instructed above. Respond ONLY with valid JSON, no other text: {\"recommended_itr_type\":\"ITR-3\",\"computed_tax_liability\":number,\"missed_deductions\":[{\"category\":string,\"estimated_amount\":number,\"note\":string}],\"depreciation_check\":string,\"presumptive_scheme_comparison\":{\"eligible\":boolean,\"estimated_tax_under_44AD\":number,\"recommendation\":string}," + taxComputationSchema + ",\"gst_pl_mismatch_flags\":[string],\"action_items\":[string]}",
  'ITR-4': "You are a meticulous Chartered Accountant's assistant preparing a tax advisory note for an individual filing ITR-4 in India under the presumptive scheme (Section 44AD/44ADA/44AE). " + taxRulesReference + " Using the extracted turnover/gross receipts text and any AIS/other-income details: 1) Verify eligibility limits (Rs.2 crore for 44AD, Rs.50 lakh for 44ADA, subject to cash-receipt threshold relaxations). 2) Calculate presumptive income and tax at the applicable rate (6%/8% for 44AD, 50% for 44ADA), showing the full computation in tax_computation (use presumptive_scheme and regular_scheme as the two keys instead of old_regime/new_regime, same line items). 3) Estimate tax under the regular books-based scheme using a reasonable expense-ratio assumption, and state which is more efficient with reasoning. 4) Flag inconsistent past use of the presumptive scheme (5-year lock-out rule under Section 44AD(4)). 5) Build tax_saving_scenarios and future_tax_planning as instructed above. Respond ONLY with valid JSON, no other text: {\"recommended_itr_type\":\"ITR-4\",\"eligible_for_presumptive\":boolean,\"presumptive_income\":number,\"presumptive_tax\":number,\"regular_scheme_estimated_tax\":number,\"recommendation\":string," + taxComputationSchema + ",\"eligibility_flags\":[string],\"action_items\":[string]}"
};

const systemPrompt = prompts[item.itr_type] || prompts['ITR-1'];
const fullPrompt = systemPrompt + clientDeclaredBlock + '\n\nHere is the extracted document text:\n\n' + pdfText + '\n\nAnalyze it as instructed and return the JSON only, with no markdown code fences.';

return [{ json: { ...item, agent_prompt: fullPrompt } }];

const prev = $('Extract Client Info from Filename').first().json;
const resp = $input.all()[0].json;
function repairTopLevelJson(text) {
  const TOP_LEVEL_KEYS = new Set([
    'recommended_itr_type','old_regime_tax','new_regime_tax','recommended_regime','regime_reasoning',
    'capital_gains','tax_computation','tax_saving_scenarios','future_tax_planning',
    'exemption_opportunities','deduction_gaps','disclosure_flags','flags','action_items'
  ]);
  let depth = 0;
  let inStr = false, esc = false;
  let result = '';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      result += c;
      if (esc) { esc = false; }
      else if (c === '\\') { esc = true; }
      else if (c === '"') { inStr = false; }
      continue;
    }
    if (c === '"') { inStr = true; result += c; continue; }
    if (c === ',') {
      const ahead = text.slice(i + 1).match(/^\s*"([a-zA-Z0-9_]+)"\s*:/);
      if (ahead && TOP_LEVEL_KEYS.has(ahead[1]) && depth > 1) {
        while (depth > 1) { result += '}'; depth--; }
      }
      result += c;
      continue;
    }
    if (c === '{' || c === '[') depth++;
    else if (c === '}' || c === ']') depth--;
    result += c;
  }
  return result;
}

function balanceBrackets(text) {
  const stack = [];
  let inStr = false, esc = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{' || c === '[') stack.push(c);
    else if (c === '}' || c === ']') stack.pop();
  }
  let out = text;
  if (inStr) out += '"';
  out = out.replace(/,\s*$/, '');
  while (stack.length) {
    out += (stack.pop() === '{') ? '}' : ']';
  }
  return out;
}

let parsed = {};
try {
  const rawText = resp.output || '{}';
  const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  try {
    parsed = JSON.parse(cleaned);
  } catch (firstErr) {
    // The AI occasionally forgets to close a nested object (e.g. tax_computation)
    // before continuing with the next top-level key. Attempt a structural repair
    // before giving up, so a single missing brace doesn't discard the whole report.
    parsed = JSON.parse(balanceBrackets(repairTopLevelJson(cleaned)));
  }
} catch (e) {
  parsed = { parse_error: true, raw: JSON.stringify(resp).slice(0, 500) };
}

function fmt(key) {
  return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

function renderValueHtml(val) {
  if (val === null || val === undefined || val === '') return '-';
  if (typeof val === 'number') return '₹' + val.toLocaleString('en-IN');
  if (typeof val === 'boolean') return val ? 'Yes' : 'No';
  return String(val);
}

function renderValue(val) {
  if (val === null || val === undefined || val === '') return '-';
  if (typeof val === 'number') return 'Rs.' + val.toLocaleString('en-IN');
  if (typeof val === 'boolean') return val ? 'Yes' : 'No';
  return String(val);
}

function renderCellContent(val) {
  if (Array.isArray(val)) {
    if (!val.length) return '<span style="color:#888;">None</span>';
    if (typeof val[0] === 'object') {
      const cols = Object.keys(val[0]);
      let t = '<table style="width:100%;border-collapse:collapse;">';
      t += '<tr>' + cols.map(c => '<th style="text-align:left;padding:4px 8px;border-bottom:1px solid #ccc;font-size:12px;color:#555;">' + fmt(c) + '</th>').join('') + '</tr>';
      for (const row of val) {
        t += '<tr>' + cols.map(c => '<td style="padding:4px 8px;border-bottom:1px solid #eee;font-size:13px;">' + renderValueHtml(row[c]) + '</td>').join('') + '</tr>';
      }
      t += '</table>';
      return t;
    }
    return '<ul style="margin:0;padding-left:18px;">' + val.map(v => '<li>' + renderValueHtml(v) + '</li>').join('') + '</ul>';
  }
  if (typeof val === 'object' && val !== null) {
    return Object.entries(val).map(([k, v]) => '<div><b>' + fmt(k) + ':</b> ' + renderValueHtml(v) + '</div>').join('');
  }
  return renderValueHtml(val);
}

const COMPUTATION_ROW_ORDER = [
  'gross_salary', 'standard_deduction', 'income_from_other_sources', 'gross_total_income',
  'chapter_via_deductions', 'net_taxable_income', 'tax_before_cess', 'rebate_87A',
  'health_education_cess', 'total_tax_payable'
];

function renderTaxComputationHtml(taxComputation) {
  if (!taxComputation || typeof taxComputation !== 'object') return '';
  const schemeKeys = Object.keys(taxComputation).filter(k => k !== 'other_income_note' && typeof taxComputation[k] === 'object');
  if (!schemeKeys.length) return '';

  const rowKeysPresent = COMPUTATION_ROW_ORDER.filter(k => schemeKeys.some(sk => taxComputation[sk] && taxComputation[sk][k] !== undefined));
  const extraKeys = new Set();
  for (const sk of schemeKeys) {
    for (const k of Object.keys(taxComputation[sk] || {})) {
      if (!COMPUTATION_ROW_ORDER.includes(k)) extraKeys.add(k);
    }
  }
  const rowKeys = rowKeysPresent.concat(Array.from(extraKeys));

  let html = '<h3 style="color:#333;margin-top:20px;">Tax Computation Sheet (for re-checking)</h3>';
  html += '<table style="width:100%;border-collapse:collapse;margin:8px 0 12px 0;">';
  html += '<tr><th style="text-align:left;padding:6px 10px;border-bottom:2px solid #333;background:#f5f5f5;">Particulars</th>' +
    schemeKeys.map(sk => '<th style="text-align:right;padding:6px 10px;border-bottom:2px solid #333;background:#f5f5f5;">' + fmt(sk) + '</th>').join('') + '</tr>';
  for (const rk of rowKeys) {
    const isTotal = rk === 'total_tax_payable';
    const rowStyle = isTotal ? 'background:#eef4ff;font-weight:700;' : '';
    html += '<tr style="' + rowStyle + '"><td style="padding:6px 10px;border-bottom:1px solid #ddd;">' + fmt(rk) + '</td>' +
      schemeKeys.map(sk => '<td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:right;">' + renderValueHtml((taxComputation[sk] || {})[rk]) + '</td>').join('') + '</tr>';
  }
  html += '</table>';
  if (taxComputation.other_income_note) {
    html += '<p style="font-size:13px;color:#555;margin-top:-4px;"><i>' + taxComputation.other_income_note + '</i></p>';
  }
  return html;
}

function renderTaxComputationPlain(taxComputation) {
  if (!taxComputation || typeof taxComputation !== 'object') return [];
  const schemeKeys = Object.keys(taxComputation).filter(k => k !== 'other_income_note' && typeof taxComputation[k] === 'object');
  if (!schemeKeys.length) return [];
  const rowKeysPresent = COMPUTATION_ROW_ORDER.filter(k => schemeKeys.some(sk => taxComputation[sk] && taxComputation[sk][k] !== undefined));
  const extraKeys = new Set();
  for (const sk of schemeKeys) {
    for (const k of Object.keys(taxComputation[sk] || {})) {
      if (!COMPUTATION_ROW_ORDER.includes(k)) extraKeys.add(k);
    }
  }
  const rowKeys = rowKeysPresent.concat(Array.from(extraKeys));
  const lines = [];
  lines.push('TAX COMPUTATION SHEET (FOR RE-CHECKING)');
  lines.push('----------------------------------------');
  lines.push('Particulars'.padEnd(28) + schemeKeys.map(sk => fmt(sk).padStart(20)).join(''));
  for (const rk of rowKeys) {
    lines.push(fmt(rk).padEnd(28) + schemeKeys.map(sk => renderValue((taxComputation[sk] || {})[rk]).padStart(20)).join(''));
  }
  if (taxComputation.other_income_note) {
    lines.push('Note: ' + taxComputation.other_income_note);
  }
  lines.push('');
  return lines;
}

function renderTaxSavingScenariosHtml(scenarios) {
  if (!Array.isArray(scenarios) || !scenarios.length) return '';
  let html = '<h3 style="color:#333;margin-top:20px;">Tax-Saving Opportunities (With Worked Examples)</h3>';
  html += '<table style="width:100%;border-collapse:collapse;margin:8px 0 12px 0;">';
  html += '<tr><th style="text-align:left;padding:6px 10px;border-bottom:2px solid #333;background:#f5f5f5;">Section</th><th style="text-align:left;padding:6px 10px;border-bottom:2px solid #333;background:#f5f5f5;">How</th><th style="text-align:right;padding:6px 10px;border-bottom:2px solid #333;background:#f5f5f5;">You Could Invest</th><th style="text-align:right;padding:6px 10px;border-bottom:2px solid #333;background:#f5f5f5;">Est. Tax Saved</th></tr>';
  for (const s of scenarios) {
    html += '<tr><td style="padding:6px 10px;border-bottom:1px solid #ddd;font-weight:600;">' + (s.section || '-') + '</td>' +
      '<td style="padding:6px 10px;border-bottom:1px solid #ddd;">' + (s.description || '-') + '</td>' +
      '<td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:right;">' + renderValueHtml(s.additional_eligible_amount) + '</td>' +
      '<td style="padding:6px 10px;border-bottom:1px solid #ddd;text-align:right;color:#0a7a2a;font-weight:700;">' + renderValueHtml(s.estimated_tax_saved) + '</td></tr>';
  }
  html += '</table>';
  return html;
}

function renderFuturePlanningHtml(items) {
  if (!Array.isArray(items) || !items.length) return '';
  let html = '<h3 style="color:#333;margin-top:20px;">Future Tax Planning (Legal Methods)</h3>';
  html += '<ul>' + items.map(v => '<li style="margin-bottom:6px;">' + renderValueHtml(v) + '</li>').join('') + '</ul>';
  html += '<p style="font-size:12px;color:#888;">These limits and rules apply for the relevant Assessment Year only and are subject to change in future Finance Acts — please reconfirm before acting on them in a later year.</p>';
  return html;
}

const recommendedType = parsed.recommended_itr_type || prev.itr_type;
const recommendedRegime = parsed.recommended_regime || parsed.recommendation || '';
const assessmentYear = prev.assessment_year || '';
const panNumber = prev.pan_number || '';

const FLAG_KEYS = ['flags', 'disclosure_flags', 'eligibility_flags', 'gst_pl_mismatch_flags'];
const SPECIAL_KEYS = ['recommended_itr_type', 'recommended_regime', 'tax_computation', 'tax_saving_scenarios', 'future_tax_planning'];

let caHtml = '<div style="font-family:Arial,sans-serif;max-width:720px;">';
caHtml += '<h2 style="color:#1a3c6e;border-bottom:2px solid #1a3c6e;padding-bottom:8px;">Tax Advisory Report — Full Analysis (For Review)</h2>';
caHtml += '<table style="width:100%;border-collapse:collapse;">';
caHtml += '<tr><td style="padding:8px;font-weight:700;background:#eef4ff;width:220px;">Client</td><td style="padding:8px;background:#eef4ff;">' + (prev.client_name || 'Unknown') + ' (' + prev.client_email + ')</td></tr>';
caHtml += '<tr><td style="padding:8px;font-weight:700;background:#eef4ff;">Recommended ITR Form</td><td style="padding:8px;background:#eef4ff;font-weight:700;color:#1a3c6e;">' + recommendedType + '</td></tr>';
if (assessmentYear) caHtml += '<tr><td style="padding:8px;font-weight:700;">Assessment Year</td><td style="padding:8px;">' + assessmentYear + '</td></tr>';
if (panNumber) caHtml += '<tr><td style="padding:8px;font-weight:700;">PAN</td><td style="padding:8px;">' + panNumber + '</td></tr>';
if (recommendedRegime) caHtml += '<tr><td style="padding:8px;font-weight:700;">Recommended Regime</td><td style="padding:8px;">' + recommendedRegime + '</td></tr>';
caHtml += '</table>';

if (parsed.parse_error) {
  caHtml += '<p style="color:#b00;margin-top:16px;">Could not fully parse the AI response. Raw output below for manual review.</p>';
  caHtml += '<pre style="white-space:pre-wrap;background:#f7f7f7;padding:10px;">' + (parsed.raw || '') + '</pre>';
} else {
  caHtml += renderTaxComputationHtml(parsed.tax_computation);
  caHtml += renderTaxSavingScenariosHtml(parsed.tax_saving_scenarios);
  caHtml += renderFuturePlanningHtml(parsed.future_tax_planning);

  caHtml += '<h3 style="color:#333;margin-top:20px;">Full Analysis Detail</h3>';
  caHtml += '<table style="width:100%;border-collapse:collapse;margin-top:8px;">';
  caHtml += '<tr><th style="text-align:left;padding:8px;border-bottom:2px solid #333;background:#f5f5f5;width:220px;">Field</th><th style="text-align:left;padding:8px;border-bottom:2px solid #333;background:#f5f5f5;">Details</th></tr>';
  for (const [key, val] of Object.entries(parsed)) {
    if (SPECIAL_KEYS.includes(key)) continue;
    const isFlagRow = FLAG_KEYS.includes(key);
    const rowBg = isFlagRow ? 'background:#fff8e1;' : '';
    caHtml += '<tr style="' + rowBg + '"><td style="padding:8px;border-bottom:1px solid #ddd;font-weight:700;vertical-align:top;' + (isFlagRow ? 'color:#8a6d00;' : '') + '">' + fmt(key) + '</td><td style="padding:8px;border-bottom:1px solid #ddd;">' + renderCellContent(val) + '</td></tr>';
  }
  caHtml += '</table>';
}
caHtml += '<p style="margin-top:24px;font-size:12px;color:#888;">Internal review copy — includes all flags and verification notes. This copy is not for the client.</p>';
caHtml += '</div>';

let clientHtml = '<div style="font-family:Arial,sans-serif;max-width:680px;">';
clientHtml += '<h2 style="color:#1a3c6e;border-bottom:2px solid #1a3c6e;padding-bottom:8px;">Your Tax Advisory Report</h2>';
clientHtml += '<table style="width:100%;border-collapse:collapse;margin-bottom:20px;background:#eef4ff;">';
clientHtml += '<tr><td style="padding:10px;font-weight:700;">Recommended ITR Form</td><td style="padding:10px;font-weight:700;color:#1a3c6e;font-size:16px;">' + recommendedType + '</td></tr>';
if (assessmentYear) clientHtml += '<tr><td style="padding:10px;font-weight:700;">Assessment Year</td><td style="padding:10px;font-weight:700;color:#1a3c6e;">' + assessmentYear + '</td></tr>';
if (recommendedRegime) clientHtml += '<tr><td style="padding:10px;font-weight:700;">Recommended Tax Regime</td><td style="padding:10px;font-weight:700;color:#1a3c6e;">' + recommendedRegime + '</td></tr>';
const taxFigureKeys = ['old_regime_tax', 'new_regime_tax', 'computed_tax_liability', 'presumptive_tax', 'regular_scheme_estimated_tax'];
for (const k of taxFigureKeys) {
  if (typeof parsed[k] === 'number') {
    clientHtml += '<tr><td style="padding:10px;font-weight:700;">' + fmt(k) + '</td><td style="padding:10px;font-weight:700;color:#1a3c6e;">' + renderValueHtml(parsed[k]) + '</td></tr>';
  }
}
clientHtml += '</table>';

if (parsed.parse_error) {
  clientHtml += '<p>Your report is being finalized. Please reach out to us if you do not receive the full details shortly.</p>';
} else {
  clientHtml += renderTaxComputationHtml(parsed.tax_computation);

  const actionItems = Array.isArray(parsed.action_items) ? parsed.action_items : [];
  if (actionItems.length) {
    clientHtml += '<h3 style="color:#333;margin-top:20px;">What You Can Do</h3>';
    clientHtml += '<ul>' + actionItems.slice(0, 6).map(v => '<li style="margin-bottom:6px;">' + renderValueHtml(v) + '</li>').join('') + '</ul>';
  }

  clientHtml += renderTaxSavingScenariosHtml(parsed.tax_saving_scenarios);
  clientHtml += renderFuturePlanningHtml(parsed.future_tax_planning);
}

clientHtml += '</div>';

const plainLines = [];
plainLines.push('TAX ADVISORY REPORT (FULL — INTERNAL REVIEW COPY)');
plainLines.push('====================');
plainLines.push('');
plainLines.push('Client Email: ' + prev.client_email);
if (panNumber) plainLines.push('PAN: ' + panNumber);
if (assessmentYear) plainLines.push('Assessment Year: ' + assessmentYear);
plainLines.push('Recommended ITR Form: ' + recommendedType);
if (recommendedRegime) plainLines.push('Recommended Tax Regime: ' + recommendedRegime);
plainLines.push('');

if (parsed.parse_error) {
  plainLines.push('NOTE: Could not fully parse the AI response.');
  plainLines.push(parsed.raw || '');
} else {
  plainLines.push(...renderTaxComputationPlain(parsed.tax_computation));

  if (Array.isArray(parsed.tax_saving_scenarios) && parsed.tax_saving_scenarios.length) {
    plainLines.push('TAX-SAVING OPPORTUNITIES (WITH WORKED EXAMPLES)');
    plainLines.push('------------------------------------------------');
    for (const s of parsed.tax_saving_scenarios) {
      plainLines.push('  * ' + (s.section || '-') + ': ' + (s.description || '-') + ' | Additional Eligible Amount: ' + renderValue(s.additional_eligible_amount) + ' | Est. Tax Saved: ' + renderValue(s.estimated_tax_saved));
    }
    plainLines.push('');
  }

  if (Array.isArray(parsed.future_tax_planning) && parsed.future_tax_planning.length) {
    plainLines.push('FUTURE TAX PLANNING (LEGAL METHODS)');
    plainLines.push('-------------------------------------');
    for (const v of parsed.future_tax_planning) plainLines.push('  - ' + renderValue(v));
    plainLines.push('  (Subject to change in future Finance Acts -- reconfirm before relying on these in a later year.)');
    plainLines.push('');
  }

  for (const [key, val] of Object.entries(parsed)) {
    if (SPECIAL_KEYS.includes(key)) continue;
    const heading = fmt(key);
    plainLines.push(heading.toUpperCase());
    plainLines.push('-'.repeat(heading.length));
    if (Array.isArray(val)) {
      if (val.length && typeof val[0] === 'object') {
        for (const row of val) {
          plainLines.push('  * ' + Object.entries(row).map(([k, v]) => fmt(k) + ': ' + renderValue(v)).join('  |  '));
        }
      } else {
        for (const v of val) plainLines.push('  - ' + renderValue(v));
      }
    } else if (typeof val === 'object' && val !== null) {
      for (const [k, v] of Object.entries(val)) plainLines.push('  ' + fmt(k) + ': ' + renderValue(v));
    } else {
      plainLines.push('  ' + renderValue(val));
    }
    plainLines.push('');
  }
}
plainLines.push('---');
plainLines.push('This is an AI-assisted advisory report reviewed by a Chartered Accountant before release. Figures are based strictly on the documents and information you supplied and should be verified against the applicable Finance Act for the relevant Assessment Year before filing. This is not a filed return.');
plainLines.push('Internal review copy — includes all flags and verification notes. Not for the client.');
const reportPlain = plainLines.join('\n');

return [{
  json: {
    client_email: prev.client_email,
    client_name: prev.client_name || 'Unknown',
    itr_type: prev.itr_type,
    assessment_year: assessmentYear,
    pan_number: panNumber,
    recommended_itr_type: recommendedType,
    parsed_report: parsed,
    report_html_ca: caHtml,
    report_html_client: clientHtml,
    report_plain: reportPlain
  }
}];

const items = $input.all();
// FIX (round 2): the built-in 'Extract PDF Text' node completely replaces each
// item's json with just {numpages, info, text, version} -- it does NOT carry
// forward client_email/pan_number/deduction_80c/etc from earlier steps, no matter
// what this node does with 'first'. So pull the client's declared info directly
// from 'Extract Client Info from Filename' by name (same pattern Parse Agent
// Response already uses for 'prev'), not from the (stripped) pipeline item.
const declaredInfo = $('Extract Client Info from Filename').first().json;

const sections = items.map((it, idx) => {
  const label = (it.binary && it.binary.data && it.binary.data.fileName) || ('Document ' + (idx + 1));
  const text = (it.json.text || '(no text extracted -- possibly unreadable or wrong password)');
  return '===== DOCUMENT: ' + label + ' =====\n' + text;
}).join('\n\n');

return [{
  json: {
    ...declaredInfo,
    document_count: items.length,
    combined_text: sections,
    text: sections
  }
}];

const matches = $input.all().map(i => i.json);
if (matches.length === 0) {
  return [{ json: { no_match: true } }];
}
matches.sort((a, b) => {
  const aTime = new Date(a.classified_at || 0).getTime();
  const bTime = new Date(b.classified_at || 0).getTime();
  return bTime - aTime;
});
return [{ json: matches[0] }];

// The trigger payload (client_name etc.) can be stale -- e.g. a manual test
// re-run, or a future upstream bug -- so treat the CRM sheet (source of truth
// used by the Intake workflow) as authoritative for client identity and tax
// figures. Only file_ids/email_body/client_email stay from this specific
// trigger event; everything else is overwritten from the matching CRM row.
const trigger = $('Has file_id?').first().json;
const crm = $input.all()[0].json;

if (crm.no_match) {
  return [{ json: { ...trigger, crm_match: false } }];
}

return [{
  json: {
    ...trigger,
    client_name: crm.name || trigger.client_name || 'Unknown',
    itr_type: crm.itr_type || trigger.itr_type,
    client_dob: crm.date_of_birth != null ? String(crm.date_of_birth) : trigger.client_dob,
    pan_number: crm.pan_number || trigger.pan_number,
    assessment_year: crm.assessment_year || trigger.assessment_year,
    financial_year: crm.financial_year || trigger.financial_year,
    deduction_80c: crm.deduction_80c != null ? String(crm.deduction_80c) : trigger.deduction_80c,
    deduction_80d: crm.deduction_80d != null ? String(crm.deduction_80d) : trigger.deduction_80d,
    deduction_80tta_ttb: crm.deduction_80tta_ttb != null ? String(crm.deduction_80tta_ttb) : trigger.deduction_80tta_ttb,
    hra_amount: crm.hra_amount != null ? String(crm.hra_amount) : trigger.hra_amount,
    home_loan_interest_24b: crm.home_loan_interest_24b != null ? String(crm.home_loan_interest_24b) : trigger.home_loan_interest_24b,
    deduction_80ccd_1b: crm.deduction_80ccd_1b != null ? String(crm.deduction_80ccd_1b) : trigger.deduction_80ccd_1b,
    crm_submission_id: crm.submission_id || null,
    crm_match: true
  }
}];
